-- FantaQuintoc: tactical coach model (PostgreSQL)
BEGIN;
CREATE TABLE IF NOT EXISTS coach_tactical_profiles (
 id BIGSERIAL PRIMARY KEY, team_name TEXT NOT NULL, coach_name TEXT NOT NULL, primary_formation TEXT NOT NULL,
 confidence SMALLINT NOT NULL CHECK(confidence BETWEEN 0 AND 100), valid_from DATE NOT NULL, valid_to DATE,
 source_note TEXT, UNIQUE(team_name, coach_name, valid_from)
);
CREATE TABLE IF NOT EXISTS coach_role_impacts (
 id BIGSERIAL PRIMARY KEY, profile_id BIGINT NOT NULL REFERENCES coach_tactical_profiles(id) ON DELETE CASCADE,
 tactical_role TEXT NOT NULL, impact_score NUMERIC(5,2) NOT NULL CHECK(impact_score BETWEEN -25 AND 25),
 evidence_kind TEXT NOT NULL DEFAULT 'TACTICAL_PRIOR', sample_size INTEGER NOT NULL DEFAULT 0,
 UNIQUE(profile_id, tactical_role)
);
CREATE TABLE IF NOT EXISTS player_tactical_scores (
 player_id BIGINT NOT NULL, profile_id BIGINT NOT NULL REFERENCES coach_tactical_profiles(id) ON DELETE CASCADE,
 tactical_role TEXT NOT NULL, role_fit NUMERIC(5,2) NOT NULL, hierarchy_score NUMERIC(5,2) NOT NULL,
 formation_frequency NUMERIC(5,2) NOT NULL, system_performance NUMERIC(5,2) NOT NULL, adaptability NUMERIC(5,2) NOT NULL,
 tactical_score NUMERIC(5,2) GENERATED ALWAYS AS (0.35*role_fit+0.25*hierarchy_score+0.15*formation_frequency+0.15*system_performance+0.10*adaptability) STORED,
 calculated_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(player_id, profile_id)
);
COMMIT;
